    ('CallableBond:CrossAssetModel:MC:engine:Pricing.Seed', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'MC', 'CallableBond', 'engine', 'Pricing.Seed', 'number', '17', null, true, 'The seed for the random number generation in the pricing.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CallableBond:CrossAssetModel:MC:engine:Pricing.Samples', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'MC', 'CallableBond', 'engine', 'Pricing.Samples', 'number', '20000', null, true, 'The number of samples to be used for the pricing phase. If this number is zero, no pricing run is performed, instead the (T0) NPV is estimated from the training phase (this result is used to fill the T0 slice of the NPV cube).', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CallableBond:CrossAssetModel:MC:engine:BrownianBridgeOrdering', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'MC', 'CallableBond', 'engine', 'BrownianBridgeOrdering', 'select', 'Steps', 'Factors,Steps,Diagonal', true, 'Variate ordering for Brownian bridges, can be Steps, Factors, Diagonal.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CallableBond:CrossAssetModel:MC:engine:SobolDirectionIntegers', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'MC', 'CallableBond', 'engine', 'SobolDirectionIntegers', 'select', 'JoeKuoD7', 'Unit,Jaeckel,SobolLevitan,SobolLevitanLemieux,JoeKuoD5,JoeKuoD6,JoeKuoD7,Kuo,Kuo2,Kuo3', true, 'Direction integers for Sobol generator, can be Unit, Jaeckel, SobolLevitan, SobolLevitanLemieux, JoeKuoD5, JoeKuoD6, JoeKuoD7, Kuo, Kuo2, Kuo3.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CallableBond:CrossAssetModel:MC:engine:MinObsDate', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'MC', 'CallableBond', 'engine', 'MinObsDate', 'select', null, 'true,false', true, 'If true the conditional expectation of each cashflow is taken from the minimum possible observation date (i.e. the latest exercise or simulation date before the cashflow''s event date); recommended setting is true.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CallableBond:CrossAssetModel:MC:engine:RegressorModel', ores_utility_system_tenant_id_fn(), 0, 'CrossAssetModel', 'MC', 'CallableBond', 'engine', 'RegressorModel', 'select', null, 'Simple,Lagged,LaggedIR,LaggedFX,LaggedEQ', false, 'Simple, LaggedFX. If not given, it defaults to Simple. Depending on the choice the regressor is built as follows: beginitemize.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:model:p', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'model', 'p', 'number', '0.0', null, true, 'The parameter p of the model that links the stock price to the default intensity.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:model:eta', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'model', 'eta', 'number', '1.0', null, true, 'The parameter eta of the model that links the stock price to the default intensity.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:model:AdjustEquityForward', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'model', 'AdjustEquityForward', 'select', 'true', 'true,false', false, 'If false, the term eta h(t,e^z) in the coefficient of v_z in the convertible bond pricing pde (see separate model documentation) is set to zero, i.e. the hazard rate h is still used in the discounting term, but the equity drift is not corrected upwards accordingly. The default value is true.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:model:AdjustEquityVolatility', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'model', 'AdjustEquityVolatility', 'select', 'false', 'true,false', false, 'If false, the market equity volatility input is not adjusted, but directly used in the pricing model. This setting is only possible if p=0. It will then set the weighting with the market survival probability S(0,t_i) in the context of formula for the equity volatility match (see separate model documentation) to zero, i.e. V is taken as the market implied volatility without adjustment. The default value is true.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:model:AdjustDiscounting', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'model', 'AdjustDiscounting', 'select', 'false', 'true,false', false, 'If false, the adjustment of the discounting rate r to the benchmark curve b is suppressed, i.e. the change of the bond pricing PDE to the bond pricing pde with benchmark curve (see separate model documentation) is em not made (see also section "Curves used in practice" in separate model documentation). The default value is true.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:model:AdjustCreditSpreadToRR', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'model', 'AdjustCreditSpreadToRR', 'select', 'true', 'true,false', false, 'If true, the credit curve h(cdot) is adjusted by a factor frac1-R1-rho where R is the recovery rate associated to the market default curve and rho is the recovery rate of the bond. Usually, R=rho, i.e. the bond recovery rate is the same as the recovery rate of the associated credit curve. In this case, the flag has no effect, since the multiplier is 1. However, when rho is overwritten with zero due to the flag ZeroRecoveryOverwrite set to true, the flag AdjustCreditSpreadToRR should also be set to true. The default value is false.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:model:ZeroRecoveryOverwrite', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'model', 'ZeroRecoveryOverwrite', 'select', 'true', 'true,false', false, 'If true, the recovery rate rho of the convertible bond is overwritten with zero. This option is usually used in conjunction with AdjustCreditSpreadToRR set to true (see below). The default value is false.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:model:TreatSecuritySpreadAsCreditSpread', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'model', 'TreatSecuritySpreadAsCreditSpread', 'select', 'true', 'true,false', true, 'If true, the security spread is not incorporated into the benchmark curve b as described above, but rather added as a spread on top of the credit curve, i.e. it is added to h(t,e^z). For exchangeables, the security spread is added to em both h^B and h^S, i.e. it simultaneously increases the credit pread of both the equity and the bond component. Since the security spread is understood as an effective discounting spread, it is scaled by s rightarrow s / (1-rho) before it is added to h, where rho is the recovery rate of the bond.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:MesherIsStatic', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'MesherIsStatic', 'select', 'true', 'true,false', true, 'Whether to use the same finite-difference mesher under scenario calculations, this is restricted to sensitivity runs.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Bootstrap.CalibrationGrid', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Bootstrap.CalibrationGrid', 'text', '6M,1Y,2Y,3Y,4Y,5Y,7Y,10Y,15Y,20Y,25Y,30Y,40Y,50Y', null, true, 'The model is calibrated on a configurable set of times. All tenors from the specified grid before the maturity date of the convertible bond are kept and the maturity date itself is added to the resulting grid to avoid calibration for times beyond the bond maturity and at the same time ensuring that we do not need to extrapolate model functions beyond the last calibration point in the pricing.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Bootstrap.StateGridPoints', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Bootstrap.StateGridPoints', 'number', '400', null, true, 'The number of state grid points of the Fokker-Planck PDE in the calibration phase.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Bootstrap.MesherEpsilon', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Bootstrap.MesherEpsilon', 'number', '1E-5', null, true, 'The mesher epsilon of the Fokker-Planck PDE in the calibration phase.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Bootstrap.MesherScaling', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Bootstrap.MesherScaling', 'number', '1.5', null, true, 'The mesher scaling multiplier of the Fokker-Planck PDE in the calibration phase.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Bootstrap.Mode', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Bootstrap.Mode', 'text', 'Alternating', null, true, 'Bootstrap strategy: "Simultaneously" or "Alternating", see separate model docs for further details.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Pricing.TimeStepsPerYear', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Pricing.TimeStepsPerYear', 'number', '24', null, true, 'The number of time steps per year to be used for the pricing PDE.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Pricing.StateGridPoints', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Pricing.StateGridPoints', 'number', '100', null, true, 'The number of state grid points to be used for the pricing PDE.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Pricing.MesherEpsilon', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Pricing.MesherEpsilon', 'number', '1E-4', null, true, 'The mesher epsilon for the pricing PDE.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:Pricing.MesherScaling', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'Pricing.MesherScaling', 'number', '1.5', null, true, 'The mesher scaling multiplier for the pricing PDE.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:ConversionRatioDiscretizationGrid', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'ConversionRatioDiscretizationGrid', 'text', null, null, true, 'Multipliers to be used for conversion ratio discretization in the presence of conversion resets / adjustments. See separate model documentation for more details.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('ConvertibleBond:DefaultableEquityJumpDiffusion:FD:engine:SensitivityTemplate', ores_utility_system_tenant_id_fn(), 0, 'DefaultableEquityJumpDiffusion', 'FD', 'ConvertibleBond', 'engine', 'SensitivityTemplate', 'reference', 'EQ_FD', null, false, 'The sensitivity template of the product. The sensitivity configuration sets shift sizes and schemes for each template.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('CreditLinkedSwap:DiscountedCashflows:DiscountingCreditLinkedSwapEngine:engine:SensitivityTemplate', ores_utility_system_tenant_id_fn(), 0, 'DiscountedCashflows', 'DiscountingCreditLinkedSwapEngine', 'CreditLinkedSwap', 'engine', 'SensitivityTemplate', 'reference', 'IR_Analytical', null, false, 'The sensitivity template of the product. The sensitivity configuration sets shift sizes and schemes for each template.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
