    ('EuropeanSwaption:LGM:Grid:model:Calibration', ores_utility_system_tenant_id_fn(), 0, 'LGM', 'Grid', 'EuropeanSwaption', 'model', 'Calibration', 'select', 'Bootstrap', 'Bootstrap,BestFit,None', true, 'How the model is fitted to the market: Bootstrap fits one instrument at a time, BestFit fits all at once, None keeps the starting values.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
    ('EuropeanSwaption:LGM:Grid:model:CalibrationStrategy', ores_utility_system_tenant_id_fn(), 0, 'LGM', 'Grid', 'EuropeanSwaption', 'model', 'CalibrationStrategy', 'select', 'CoterminalDealStrike', 'CoterminalDealStrike,CoterminalATM,DeltaGammaAdjusted,None', true, 'Which swaptions the fit uses: those that end with the deal and start at the money, those at the strike of the deal, or the delta gamma adjusted set.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
