    ('ForwardBond:DiscountedCashflows:DiscountingForwardBondEngine:engine:SpreadOnIncomeCurve', ores_utility_system_tenant_id_fn(), 0, 'DiscountedCashflows', 'DiscountingForwardBondEngine', 'ForwardBond', 'engine', 'SpreadOnIncomeCurve', 'select', 'true', 'true,false', false, 'Whether to apply the security spread on the income curve for compounding, default to false.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
