    ('ForwardBond:DiscountedCashflows:DiscountingForwardBondEngine:engine:TimestepPeriod', ores_utility_system_tenant_id_fn(), 0, 'DiscountedCashflows', 'DiscountingForwardBondEngine', 'ForwardBond', 'engine', 'TimestepPeriod', 'tenor', '3M', null, false, 'Discretization interval for zero bond pricing, defaults to 3M if not given discounting of intermediate bond cashflows.', 'ores_analytics_service', 'system.initial_load', 'Seed pricing engine vocabulary'),
